B.Q4=new A.dE("sozlesmeli_hastalik","4/B s\xf6zle\u015fmeli personelin hastal\u0131k izni","S\xf6zle\u015fmeli hastal\u0131k izni","S\xf6zle\u015fmeli personel hastal\u0131k izni nas\u0131l verilir?",B.adK,"Resm\xee tabip raporuyla kan\u0131tlanan hastal\u0131klar i\xe7in s\xf6zle\u015fmeli personele \xfccretli hastal\u0131k izni verilebilir. Hastal\u0131k nedeniyle Sosyal G\xfcvenlik Kurumunca \xf6denen ge\xe7ici i\u015f g\xf6remezlik \xf6dene\u011fi ilgilinin \xfccretinden d\xfc\u015f\xfcl\xfcr. Ka\xe7 g\xfcn izin verilece\u011fine ili\u015fkin s\xfcre ibaresi Dan\u0131\u015ftay karar\u0131yla iptal edildi\u011finden metinde s\xfcre yazm\u0131yor; bu y\xfczden g\xfcn say\u0131s\u0131n\u0131 bu metinden s\xf6yleyemiyorum.",B.a8T,"Rapor s\xfcresi ve \xfccret konusunda kesin bilgi i\xe7in kurumunun personel birimine dan\u0131\u015f.",u.I,B.fe)
B.a6U=s(["sozlesmeli","4/b","esaslar","calisma saat","calisma sure","haftalik calisma","mesai","fazla mesai","fazla calisma","nobet"],t.s)
B.ajb=new A.bx("S\xf6zle\u015fmeli Personel \xc7al\u0131\u015ft\u0131r\u0131lmas\u0131na \u0130li\u015fkin Esaslar, md. 13 (\xc7al\u0131\u015fma saatleri)","Devlet memurlar\u0131 i\xe7in saptanan \xe7al\u0131\u015fma saat ve s\xfcreleri s\xf6zle\u015fmeli personel i\xe7in de uygulan\u0131r")
B.aiL=new A.bx("S\xf6zle\u015fmeli Personel \xc7al\u0131\u015ft\u0131r\u0131lmas\u0131na \u0130li\u015fkin Esaslar, md. 13 (Fazla \xe7al\u0131\u015fma)","Bu Karar Esaslar\u0131na g\xf6re \xe7al\u0131\u015ft\u0131r\u0131lacak s\xf6zle\u015fmeli personel o g\xfcn bitirilmesi gereken i\u015flerin bitimine kadar \xe7al\u0131\u015fmak zorundad\u0131r. Normal \xe7al\u0131\u015fma s\xfcrelerini a\u015fan bu s\xfcreler i\xe7in ilgili kanunlar\u0131nda \xf6ng\xf6r\xfclen h\xfck\xfcmler sakl\u0131 kalmak kayd\u0131yla her sekiz saati i\xe7in bir g\xfcn hesab\u0131yla izin verilir.")
